	        label
	            .append('span')
	            .text(function(d) {
	                if (name === 'feature') {
	                    return d.title;
	                }
	                return t(name + '.' + d + '.description');
	            });

	        // Update
	        items = items
	            .merge(enter);

	        items
	            .classed('active', active)
	            .selectAll('input')
